/**
 * Friendship Test (Know Me Better) Question Bank & Prompts
 * Every option includes curated visual illustration metadata (crisp circular SVG).
 */

export interface FriendshipOption {
  text: string;
  image: string;
}

export interface FriendshipQuestionTemplate {
  id: string;
  category: 'habits' | 'food' | 'travel' | 'reactions' | 'preferences' | 'personality' | 'lovers' | 'gen_z' | 'chaos';
  prompt: string;
  options: [FriendshipOption, FriendshipOption, FriendshipOption, FriendshipOption];
}

export interface SanitizedQuestion {
  id: string;
  prompt: string;
  options: Array<FriendshipOption | string>;
  isCustom?: boolean;
}

export interface CreatorQuestionItem {
  id: string;
  prompt: string;
  options: Array<FriendshipOption | string>;
  correctIndex: number;
  isCustom?: boolean;
}

export const QUIZ_LENGTH_OPTIONS = [10, 15, 20] as const;
export type QuizLength = typeof QUIZ_LENGTH_OPTIONS[number];
export const DEFAULT_QUIZ_LENGTH: QuizLength = 10;
export const MAX_CUSTOM_QUESTIONS = 3;

/**
 * Safe accessor for option text
 */
export function getOptionText(opt: FriendshipOption | string): string {
  return typeof opt === 'string' ? opt : opt.text;
}

/**
 * Safe accessor for option image with instant SVG fallback
 */
export function getOptionImage(opt: FriendshipOption | string, index: number = 0): string {
  if (typeof opt !== 'string' && opt && opt.image) {
    return opt.image;
  }
  const letter = ['A', 'B', 'C', 'D'][index % 4];
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 160 160" width="160" height="160"><defs><linearGradient id="fallbackG" x1="0%" y1="0%" x2="100%" y2="100%"><stop offset="0%" stop-color="#3b4cca"/><stop offset="100%" stop-color="#13315c"/></linearGradient></defs><circle cx="80" cy="80" r="74" fill="url(#fallbackG)"/><circle cx="80" cy="80" r="68" fill="none" stroke="#d4b483" stroke-width="2" stroke-opacity="0.8"/><circle cx="80" cy="80" r="32" fill="#ffffff" fill-opacity="0.95" stroke="#d4b483" stroke-width="2"/><text x="80" y="91" font-family="system-ui, sans-serif" font-size="30" font-weight="900" fill="#0b2545" text-anchor="middle">${letter}</text></svg>`;
  return `data:image/svg+xml;utf8,${encodeURIComponent(svg)}`;
}

